package local.hy320.helperstarter;
import android.content.Context;import android.net.nsd.*;import android.os.*;import java.util.*;
/** Uses Android's native pairing server with a fresh six-digit secret and resolves only its own unique service. */
@android.annotation.TargetApi(34)
final class NativePairing {
 private final Object adb;private final NsdManager nsd;private final Handler main=new Handler(Looper.getMainLooper());private IBinder listener;private boolean active,resolving;private long generation;private String code;private int port;private String address;private NsdManager.ResolveListener resolve;private IBinder.DeathRecipient death;private Runnable timeout;
 private static Object service(String name,String api)throws Exception{IBinder binder=(IBinder)Class.forName("android.os.ServiceManager").getMethod("getService",String.class).invoke(null,name);return Class.forName(api).getMethod("asInterface",IBinder.class).invoke(null,binder);}
 NativePairing(Context context)throws Exception{adb=service("adb","android.debug.IAdbManager$Stub");nsd=(NsdManager)NsdManager.class.getConstructor(Context.class,Class.forName("android.net.nsd.INsdManager")).newInstance(context,service("servicediscovery","android.net.nsd.INsdManager$Stub"));}
 synchronized Bundle start(IBinder target)throws Exception{
  if(active)throw new IllegalStateException("A pairing window is already open.");if(target==null||!target.isBinderAlive())throw new IllegalArgumentException("Pairing display unavailable");active=true;long token=++generation;listener=target;death=()->main.post(this::close);listener.linkToDeath(death,0);code=String.format(Locale.ROOT,"%06d",new java.security.SecureRandom().nextInt(1_000_000));port=0;address=null;String name="cytv-"+UUID.randomUUID();
  try{adb.getClass().getMethod("enablePairingByQrCode",String.class,String.class).invoke(adb,name,code);NsdServiceInfo request=new NsdServiceInfo();request.setServiceName(name);request.setServiceType("_adb-tls-pairing._tcp.");resolve=new NsdManager.ResolveListener(){public void onResolveFailed(NsdServiceInfo info,int reason){fail(token);}public void onServiceResolved(NsdServiceInfo info){synchronized(NativePairing.this){if(!active||generation!=token)return;resolving=false;if(!name.equals(info.getServiceName())||info.getPort()<1||info.getPort()>65535||!local(info.getHost())){fail(token);return;}port=info.getPort();address=info.getHost().getHostAddress();send(state());}}};
   main.postDelayed(()->{synchronized(NativePairing.this){if(!active||generation!=token)return;resolving=true;try{nsd.resolveService(request,resolve);}catch(RuntimeException failure){fail(token);}}},700);
   timeout=()->{synchronized(NativePairing.this){if(active&&generation==token){Bundle expired=new Bundle();expired.putBoolean("expired",true);send(expired);close();}}};main.postDelayed(timeout,120_000);return state();
  }catch(Exception failure){close();throw failure;}
 }
 private static boolean local(java.net.InetAddress host){if(host==null)return false;try{for(java.net.NetworkInterface nic:Collections.list(java.net.NetworkInterface.getNetworkInterfaces()))for(java.net.InetAddress address:Collections.list(nic.getInetAddresses()))if(address.equals(host))return true;}catch(java.net.SocketException ignored){}return false;}
 private synchronized Bundle state(){Bundle b=new Bundle();b.putString("code",code);b.putInt("port",port);b.putString("address",address);return b;}
 private synchronized void fail(long token){if(!active||generation!=token)return;Bundle failed=new Bundle();failed.putBoolean("failed",true);send(failed);close();}
 private void send(Bundle state){IBinder target=listener;if(target==null)return;long identity=Binder.clearCallingIdentity();Parcel data=Parcel.obtain();try{data.writeInterfaceToken("com.gathin.tvhome.NativePairing.v1");data.writeBundle(state);target.transact(IBinder.FIRST_CALL_TRANSACTION,data,null,IBinder.FLAG_ONEWAY);}catch(RemoteException dead){main.post(this::close);}finally{data.recycle();Binder.restoreCallingIdentity(identity);}}
 synchronized void close(){++generation;if(timeout!=null)main.removeCallbacks(timeout);timeout=null;if(resolving&&resolve!=null)try{NsdManager.class.getMethod("stopServiceResolution",NsdManager.ResolveListener.class).invoke(nsd,resolve);}catch(Exception ignored){}resolving=false;resolve=null;if(active)try{adb.getClass().getMethod("disablePairing").invoke(adb);}catch(Exception failure){android.util.Log.w("SettingsSession","Android pairing cancellation was not confirmed");}active=false;if(listener!=null&&death!=null)try{listener.unlinkToDeath(death,0);}catch(java.util.NoSuchElementException ignored){}listener=null;death=null;code=null;port=0;address=null;}
}
